"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77984"],{16390(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.predicado_obrigatorio","status":422,"titulo":"Predicado obrigat\xf3rio"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.predicado_obrigatorio","requisitos":["UNI-REQ-0018"],"oQueAconteceu":["O campo `predicado` n\xe3o veio no corpo da requisi\xe7\xe3o, ou veio com valor nulo. O predicado \xe9 a\\nexig\xeancia em si, o que a regra cobra do processo seletivo na avalia\xe7\xe3o de conformidade: etapa\\nobrigat\xf3ria, modalidades m\xednimas, documento por modalidade, atendimento dispon\xedvel, crit\xe9rio de\\ndesempate, concorr\xeancia dupla ou uma regra transit\xf3ria. Sem ele n\xe3o h\xe1 o que avaliar. Nada \xe9\\ngravado.","O erro vale s\xf3 para a aus\xeancia. Um predicado que veio, mas est\xe1 mal formado, \xe9 recusado por outro\\nc\xf3digo: lista vazia de modalidades\\n([`modalidades_minimas_vazia`](/erros/uniplus.selecao.obrigatoriedade_legal.modalidades_minimas_vazia)),\\nlista vazia de tipos de defici\xeancia\\n([`atendimento_disponivel_vazio`](/erros/uniplus.selecao.obrigatoriedade_legal.atendimento_disponivel_vazio))\\ne c\xf3digo em branco\\n([`predicado_com_codigo_em_branco`](/erros/uniplus.selecao.obrigatoriedade_legal.predicado_com_codigo_em_branco)).\\nUm predicado que n\xe3o traz o discriminador `$tipo` n\xe3o chega a este erro: o corpo n\xe3o pode ser lido e a\\nrecusa \xe9 de\\n[requisi\xe7\xe3o malformada](/erros/uniplus.requisicao.malformada), com status 400.","A aus\xeancia \xe9 uma recusa de dom\xednio, com status 422, e n\xe3o de leitura do corpo. A resposta lista todas\\nas viola\xe7\xf5es de campo da mesma requisi\xe7\xe3o em `errors[]`, cada uma com o campo em camelCase, o c\xf3digo e\\na mensagem; o `code` principal da resposta \xe9 o da primeira viola\xe7\xe3o, na ordem em que os campos s\xe3o conferidos (tipo\\nde processo, categoria, c\xf3digo da regra, predicado, descri\xe7\xe3o, base legal, ato normativo, portaria\\ninterna e vig\xeancia).","A confer\xeancia vem depois da permiss\xe3o para manter obrigatoriedades legais e da leitura do corpo, e\\nantes de qualquer consulta: na atualiza\xe7\xe3o, antes de a regra ser buscada\\n([`nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.nao_encontrada)); nas duas opera\xe7\xf5es,\\nantes da confer\xeancia do tipo de processo e dos c\xf3digos que o predicado cita."],"comoResolver":["Informe o predicado no corpo, com o `$tipo` da exig\xeancia e os campos que ele pede; o contrato de cada\\ntipo est\xe1 na refer\xeancia de API do m\xf3dulo Sele\xe7\xe3o. Na atualiza\xe7\xe3o, a regra \xe9 substitu\xedda por inteiro:\\nreenvie tamb\xe9m os campos que n\xe3o mudam, porque o que n\xe3o for enviado \xe9 tratado como ausente."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);